
/**
 * Module dependencies.
 */

var assert = require('assert');
var shExpMatch = require('../shExpMatch');

describe('shExpMatch(str, shexp)', function () {

  var tests = [
    ["http://example.invalid/people/ari/index.html", "*/ari/*", true],
    ["http://example.invalid/people/montulli/index.html", "*/ari/*", false],
    ["http://example.invalid/people/index.html", ".*/people/.*", true],
    ["http://example.invalid/people/yourpage/index.html", ".*/mypage/.*", false],
    ["example.invalid", "*example.invalid*", true],
    ["example.invalid?email=user@example.invalid", "*example.invalid*", true],
    ["example.invalid", "(*.example.invalid|example.invalid)", true],
    ["example.invalid", "(*.example.invalid|example.invalid)", true],
    ["example.invalid", "(*.example.invalid|example.invalid)", false],
    ["example.invalid", "?.com", true],
    ["example.invalid", "?.com", true],
    ["example.invalid", "?.com", false]
  ];

  tests.forEach(function (test) {
    var expected = test.pop();
    it('should return `' + expected +'` for "' + test.join('", "') + '"', function () {
      assert.equal(expected, shExpMatch(test[0], test[1]));
    });
  });

});
